{"attempt":"1 / 5","score":"1","callout":"STRIKE!","wind":"22"}
### Ran Playwright code
```js
await (async page => { const b=page.locator("#shootButton"); await b.hover(); await page.mouse.down(); await page.waitForTimeout(650); await page.mouse.up(); await page.waitForTimeout(2200); return {attempt: await page.locator("#attemptLabel").innerText(), score: await page.locator("#playerScore").innerText(), callout: await page.locator("#shotCallout").innerText(), wind: await page.locator("#windSpeed").innerText()}; })(page);
